// Check if message contains attachments
const hasAttachments = item => {
  // Check if attachments array exists and has entries
  if (item.json.attachments && Array.isArray(item.json.attachments) && item.json.attachments.length > 0) {
    return true;
  }

  // Also check for binary data that could contain attachments
  if (item.binary) {
    const binaryKeys = Object.keys(item.binary);
    for (const key of binaryKeys) {
      if (item.binary[key].mimeType !== 'text/plain' && item.binary[key].mimeType !== 'text/html') {
        return true;
      }
    }
  }

  return false;
};

// Get attachment type if exists
const getAttachmentTypes = (item) => {
  const types = new Set();

  // Check explicit attachments array
  if (item.json.attachments && Array.isArray(item.json.attachments)) {
    item.json.attachments.forEach(attachment => {
      if (attachment.contentType) {
        types.add(attachment.contentType.split('/')[0]);
      }
    });
  }

  // Check binary data
  if (item.binary) {
    const binaryKeys = Object.keys(item.binary);
    for (const key of binaryKeys) {
      if (item.binary[key].mimeType !== 'text/plain' && item.binary[key].mimeType !== 'text/html') {
        const mainType = item.binary[key].mimeType.split('/')[0];
        types.add(mainType);
      }
    }
  }

  return Array.from(types);
};

const inputItems = $input.all();
const outputItems = [];

for (const item of inputItems) {
  // Determine if the message has attachments
  const hasAttachment = hasAttachments(item);

  // Get types of attachments if any
  const attachmentTypes = hasAttachment ? getAttachmentTypes(item) : [];

  const newItem = {
    json: {
      ...item.json,
      hasAttachment,
      attachmentTypes,
      // Create simple flags for common attachment types
      hasImageAttachment: attachmentTypes.includes('image'),
      hasPdfAttachment: attachmentTypes.some(type => item.json.attachments?.some(a => a.contentType === 'application/pdf') || 
                                              (item.binary && Object.values(item.binary).some(b => b.mimeType === 'application/pdf'))),
      hasDocumentAttachment: attachmentTypes.includes('application') || 
                             (item.binary && Object.values(item.binary).some(b => 
                               b.mimeType.includes('document') || 
                               b.mimeType.includes('msword') || 
                               b.mimeType.includes('officedocument'))),
      attachmentNames: item.json.attachments ? item.json.attachments.map(a => a.filename) : 
                      (item.binary ? Object.values(item.binary).map(b => b.fileName).filter(name => name) : []),
      // Create a user-friendly summary
      attachmentSummary: hasAttachment ? 
        `Email contains ${attachmentTypes.length} type(s) of attachments: ${attachmentTypes.join(', ')}` : 
        'Email has no attachments'
    }
  };

  // Keep binary data intact
  if (item.binary) {
    newItem.binary = item.binary;
  }

  outputItems.push(newItem);
}

return outputItems;

// Process image attachment
const item = $input.item;
return {
  json: {
    ...item.json,
    message: "Processing image attachment(s)",
    imageAttachments: item.json.attachmentNames.filter(name => {
      const ext = name.split('.').pop().toLowerCase();
      return ['jpg', 'jpeg', 'png', 'gif', 'bmp', 'webp', 'svg', 'tiff'].includes(ext);
    })
  },
  binary: item.binary
};

// Process PDF attachment
const item = $input.item;
return {
  json: {
    ...item.json,
    message: "Processing PDF attachment(s)",
    pdfAttachments: item.json.attachmentNames.filter(name => name.toLowerCase().endsWith('.pdf'))
  },
  binary: item.binary
};

// Process document attachment
const item = $input.item;
return {
  json: {
    ...item.json,
    message: "Processing document attachment(s)",
    documentAttachments: item.json.attachmentNames.filter(name => {
      const ext = name.split('.').pop().toLowerCase();
      return ['doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx', 'txt', 'rtf', 'odt', 'ods', 'odp'].includes(ext);
    })
  },
  binary: item.binary
};

// Process for no attachments case
const item = $input.item;
return {
  json: {
    ...item.json,
    message: "Email has no attachments"
  }
};
